import math

def count_divisors(n):
    """Counts the total number of positive divisors of n, tau(n)."""
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    """Calculates d(n), the number of positive divisors of n other than 1 and n."""
    if n <= 0:
        # Not defined for non-positive integers, but we are checking positive n.
        return -1
    if n == 1:
        return 0
    tau_n = count_divisors(n)
    # d(n) = tau(n) - 2 (since we exclude 1 and n)
    return tau_n - 2

# Brute-force search parameters
N_limit = 1000
min_a = float('inf')
results = []

for n in range(1, N_limit + 1):
    n_plus_735 = n + 735

    dn = d(n)
    dn_plus_735 = d(n_plus_735)

    if dn == dn_plus_735:
        a = dn

        # We are looking for the *least* nonnegative integer 'a'.
        if a < min_a:
            min_a = a
            results = [(n, a)]
        elif a == min_a:
            results.append((n, a))
        # Optimization: If we find a=0, we can stop immediately because 0 is the smallest possible non-negative value.
        if a == 0:
            break

# Check if the smallest 'a' found is 0. If so, we found the answer quickly.
if min_a == 0:
    print(f"Found smallest a = 0. Corresponding n: {results[0][0]}")
elif min_a != float('inf'):
    print(f"Smallest a found = {min_a}. Corresponding n: {results}")
else:
    print("No matches found up to N=1000.")

